presets.css:
/* puff仿微信(日间) by点星 禁止二传*/

/* ---------- 顶栏外层：去掉左右留白，强制拉满 ---------- */
.chat-thread-top {
  left: 0;
  right: 0;
  top: 0;
  width: 100%;
  padding-left: 0;
  padding-right: 0;
  margin-left: 0;
  margin-right: 0;
  box-sizing: border-box;
}

/* ---------- 顶栏胶囊：通栏贴顶，实底 #eeeeee，加高 ---------- */
.chat-thread-pill {
  border-radius: 0;
  border: none;
  border-bottom: 1px solid var(--dress-header-border);
  box-shadow: none;
  width: 100%;
  max-width: none;
  margin: 0;
  min-height: 64px;
  height: auto;
  padding-top: 16px;
  padding-bottom: 16px;
  padding-left: 14px;
  padding-right: 14px;
  box-sizing: border-box;
  background: #eeeeee;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

/* ---------- 顶栏左一：返回键换图 + 放大 + 往下挪一点点 ---------- */
.chat-back,
.chat-back-wrap {
  width: 19px;
  height: 19px;
  background-image: url("https://imgbed.heliar.top/i/y8whJyiub_soft_w_dc1ff442a623beed553d210c35f10d6f.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  color: transparent;
  font-size: 0;
  transform: translateY(2px); /* 往下挪一点点，想更下就加大 */
}
.chat-back svg,
.chat-back i,
.chat-back-wrap svg,
.chat-back-wrap i {
  opacity: 0;
}

/* ---------- 顶栏右一：更多键换图 + 放大（不动右二心声） ---------- */
.chat-thread-head-more {
  width: 19px;
  height: 19px;
  background-image: url("https://imgbed.heliar.top/i/hmgfnh_XVkYLAeSK_b1e11d251bffb372ddc18a28cfafd57d.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  color: transparent;
  font-size: 0;
}
.chat-thread-head-more svg,
.chat-thread-head-more i,
.chat-thread-head-more img {
  opacity: 0;
}

/* ---------- 顶栏右二：隐藏原生图标，保留可点击 ---------- */
.chat-thread-head-xinsheng svg,
.chat-thread-head-xinsheng i,
.chat-thread-head-xinsheng img,
.chat-thread-head-xinsheng::before,
.chat-thread-head-xinsheng::after {
  opacity: 0;
}

/* ---------- 顶栏标题：字号大一号 + 往下移一点 ---------- */
.chat-thread-center h2 {
  font-size: 16px;
  transform: translateY(3px);
}

/* ---------- 底栏外层：去掉左右留白，强制拉满 ---------- */
.chat-compose {
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  padding-left: 0;
  padding-right: 0;
  padding-bottom: 0;
  margin-left: 0;
  margin-right: 0;
  box-sizing: border-box;
}

/* ---------- 底栏胶囊：通栏贴底，实底 #f2f2f2，高度 64 ---------- */
.chat-compose-bar {
  border-radius: 0;
  border: none;
  border-top: 1px solid var(--dress-compose-bar-border);
  box-shadow: none;
  width: 100%;
  max-width: none;
  margin: 0;
  min-height: 64px;
  height: auto;
  padding-top: 12px;
  padding-bottom: 12px;
  padding-left: 12px;
  padding-right: 12px;
  box-sizing: border-box;
  background: #f2f2f2;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

/* ---------- 滚动区留白，避免被顶/底栏压住 ---------- */
.chat-thread-scroll {
  padding-top: calc(env(safe-area-inset-top, 0px) + 72px);
  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 72px);
}


/* ========== 底栏左一：加号键换图 ========== */
.chat-compose-plus {
  width: 27px;
  height: 27px;
  background-image: url("https://imgbed.heliar.top/i/CYJoHHw_UzJnFAdM_befb5f75266f280ec093300b91038909.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  color: transparent;
  font-size: 0;
}
.chat-compose-plus svg,
.chat-compose-plus i,
.chat-compose-plus img {
  opacity: 0;
}

/* ========== 底栏右：AI 回复键换图 ========== */
.chat-compose-icon.is-reply {
  width: 27px;
  height: 27px;
  background-image: url("https://imgbed.heliar.top/i/Be90GqXO0XtiY7jb_32960616ccdd2decf225aedd2070b23c.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  color: transparent;
  font-size: 0;
}
.chat-compose-icon.is-reply svg,
.chat-compose-icon.is-reply i,
.chat-compose-icon.is-reply img {
  opacity: 0;
}

/* ========== 底栏：麦克风键换图 ========== */
.chat-compose-icon.is-voice {
  width: 27px;
  height: 27px;
  background-image: url("https://imgbed.heliar.top/i/Rctbgk9EcteGKoh3_b8628d44c34ef3a133f906e916d3f87c.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  color: transparent;
  font-size: 0;
}
.chat-compose-icon.is-voice svg,
.chat-compose-icon.is-voice i,
.chat-compose-icon.is-voice img {
  opacity: 0;
}

/* ========== 底栏三个键：统一往上挪 ========== */
.chat-compose-plus,
.chat-compose-icon.is-reply,
.chat-compose-icon.is-voice {
  transform: translateY(-5px); /* 往上挪，想更上就加大 */
}

/* ========== 底栏钉死，点击不往上抬 ========== */
.chat-compose {
  bottom: 0 !important;
  transform: none !important;
  transition: none !important;
}
.chat-compose-bar {
  transform: none !important;
  margin-bottom: 0 !important;
  transition: none !important;
}
/* 若上抬来自键盘/安全区，把下内边距也钉住 */
.chat-compose {
  padding-bottom: 0 !important;
}

/* ========== 底栏输入框：偏白的灰白底 + 圆角 + 隐藏提示词 ========== */

.chat-compose-input {
  background: #fdfdfd;         /* 偏白，只差纯白一丝；想更白改 #fefefe */
  border-radius: 6.5px;
  border: none;
  box-shadow: none;
  color: var(--dress-compose-bar-fg);
  margin-left: 2.5px;
  margin-right: 2.5px;
  padding-left: 10px;
  padding-right: 10px;
}

.chat-compose-input::placeholder {
  color: transparent;
  opacity: 0;
}

/* 若外层还有壳，一起灰白底圆角，避免露灰 */
.chat-compose-input-wrap,
.chat-compose-input-box {
  background: #fdfdfd;
  border-radius: 6.5px;
  border: none;
  box-shadow: none;
  margin-left: 2.5px;
  margin-right: 2.5px;
}

.chat-compose-input:focus,
.chat-compose-input:focus-visible {
  outline: none;
  box-shadow: none;
}


/* ========== 发送键：放大 + 上移对齐其它三键 ========== */
.chat-compose-icon.is-send.ready {
  width: 28px;
  height: 28px;
  background-color: transparent;
  background-image: url("https://imgbed.heliar.top/i/170fcf_sDxkiwaIr_6e4b1e02f1b8cf37097430b82c5f4dc8.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  border: none;
  border-radius: 0;
  box-shadow: none;
  color: transparent;
  font-size: 0;
  padding: 0;
  overflow: visible;
  transform: translateY(-5px);   /* 和加号/AI/麦克风同款上移 */
}
.chat-compose-icon.is-send.ready svg,
.chat-compose-icon.is-send.ready i,
.chat-compose-icon.is-send.ready img {
  opacity: 0;
}
.chat-compose-icon.is-send.ready::before,
.chat-compose-icon.is-send.ready::after {
  display: none;
  background: none;
  border: none;
  box-shadow: none;
}

/* ========== 输入框装饰图标：无文字显示，有文字隐藏 ========== */

.chat-compose-bar::after {
  content: "";
  position: absolute;
  right: 90px; /* 数字越大越往左 */
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  background-image: url("https://imgbed.heliar.top/i/NbBJKCLzCjDNmb1__a672186f8134b2153c1dca6b1f0ccbd6.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.15s;
}

/* 输入框有内容时，隐藏装饰图标 */
.chat-compose-bar:has(.chat-compose-input:not(:placeholder-shown))::after {
  opacity: 0;
}


/* ========== A. 主题变量（微圆角，气泡整体略缩小） ========== */
.chat-thread {
  /* 我方气泡：微信绿 */
  --dress-bubble-me-bg: #95EC69;
  --dress-bubble-me-fg: #000000;
  --dress-bubble-me-border: none;
  --dress-bubble-me-shadow: 0 2px 10px rgba(0, 0, 0, 0.06);
  --dress-bubble-me-radius: 4px;

  /* 对方气泡：纯白 */
  --dress-bubble-them-bg: #ffffff;
  --dress-bubble-them-fg: var(--ink);
  --dress-bubble-them-border: none;
  --dress-bubble-them-shadow: 0 2px 12px rgba(0, 0, 0, 0.05);
  --dress-bubble-them-radius: 4px;
}

/* 气泡整体增大一点点：内边距微调 */
.chat-bubble {
  padding: 8.5px 10.5px !important;   /* 原 7.5px 9.5px → 8.5px 10.5px */
}

/* ========== 气泡、语音容器开启相对定位，允许伪元素溢出 ========== */
.chat-bubble,
.puff-voice-pill {
  position: relative;
  overflow: visible !important;
}

/* 外层全部放行溢出，三角不被裁切【核心】 */
.chat-msg,
.chat-msg-body,
.chat-bubble,
.chat-bubble-primary,
.puff-voice-pill {
  position: relative !important;
  overflow: visible !important;
}

/* ---------------- 对方气泡｜左侧尖角 ---------------- */
.chat-msg.is-them .chat-bubble::before,
.chat-msg.is-them .puff-voice-pill::before {
  content: "";
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  left: -6px;
  width: 8px;
  height: 16px;
  background-color: var(--dress-bubble-them-bg);
  clip-path: polygon(0 50%, 100% 0, 100% 100%);
  border-radius: 1px;
  z-index: 2;
}

/* ---------------- 我方气泡｜右侧尖角 ---------------- */
.chat-msg.is-me .chat-bubble::after,
.chat-msg.is-me .puff-voice-pill::after {
  content: "";
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  right: -6px;
  width: 8px;
  height: 16px;
  background-color: var(--dress-bubble-me-bg);
  clip-path: polygon(100% 50%, 0 0, 0 100%);
  border-radius: 1px;
  z-index: 2;
}

/* 屏蔽图片、表情包气泡的三角 */
.chat-msg.has-image .chat-bubble::before,
.chat-msg.has-sticker .chat-bubble::before,
.chat-msg.has-image .chat-bubble::after,
.chat-msg.has-sticker .chat-bubble::after {
  display: none !important;
}


/* ========== 头像：缩小 + 方形微圆角 + 去掉头像框 ========== */
.chat-ava,
.chat-ava-sm {
  width: 38px !important;          /* 原 44px → 38px，缩小 */
  height: 38px !important;
  border-radius: 6px !important;
  object-fit: cover !important;
  overflow: hidden !important;
  flex-shrink: 0;
  display: block;
  /* 去掉头像框 */
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  background: transparent !important;
  padding: 0 !important;
}

/* 若头像是「容器 + img」结构，内层也一起去框缩角 */
.chat-ava > img,
.chat-ava-sm > img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 6px !important;
  display: block;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
}

/* ========== 头像：往上移 ========== */
.chat-ava,
.chat-ava-sm {
  transform: translateY(-3px);
}

/* ========== 对方名字：不显示，但把高度留成原来的一半左右 ========== */
.chat-msg.is-them .chat-msg-name {
  visibility: hidden !important;   /* 看不见 */
  height: 8px !important;          /* 关键：给它一个固定高度，撑住气泡位置 */
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 0 !important;
  font-size: 0 !important;
}

/* ========== 对方消息行：间距缩小 ========== */
.chat-msg.is-them {
  margin-bottom: 5px !important; /* 数字越小间距越小 */
}

/* 确保对方名字不占额外高度（承接上一版） */
.chat-msg.is-them .chat-msg-name {
  visibility: hidden !important;
  height: 8px !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 0 !important;
  font-size: 0 !important;
}

/* ========== 语音气泡：与文字气泡同款圆角 / 底色 ========== */
.chat-msg.is-me .puff-voice-pill {
  background: var(--dress-bubble-me-bg);
  border-radius: 4px !important;     /* 和文字气泡一致的微圆角 */
  border: none !important;
  box-shadow: none !important;
  color: var(--dress-bubble-me-fg);
}

.chat-msg.is-them .puff-voice-pill {
  background: var(--dress-bubble-them-bg);
  border-radius: 4px !important;
  border: none !important;
  box-shadow: none !important;
  color: var(--dress-bubble-them-fg);
}

/* 语音气泡的内层也别用圆角盖住（有些版本里面还包一层） */
.puff-voice-pill > * {
  border-radius: 4px;
}


/* ========== 转账卡片：橙色底 + 白字 + 左侧图标 + 小三角 ========== */
.puff-transfer {
  position: relative;
  background: #FA9D3B !important;
  color: #ffffff !important;
  border: none !important;
  border-radius: 8px;
  padding-left: 44px !important;   /* 给左侧图标留位 */
}

/* 卡片内所有文字白色 */
.puff-transfer *,
.puff-transfer .puff-transfer-title,
.puff-transfer .puff-transfer-amount,
.puff-transfer .puff-transfer-desc {
  color: #ffffff !important;
}

/* ========== 转账卡片：左侧图标放大 + 上移 + 左移 ========== */
.puff-transfer::before {
  content: "";
  position: absolute;
  left: 8px;                      /* 原 12px → 8px，往左挪 */
  top: 46%;                       /* 原 50% → 46%，往上挪 */
  transform: translateY(-50%);
  width: 32px;                    /* 原 24px → 32px，放大 */
  height: 32px;
  background-image: url("https://imgbed.heliar.top/i/Aw8QBYD8U7xSlKZa_retouch_2026081517164094.webp");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
}

/* 橙色小三角（尖朝外） */
/* 我方：右侧小三角 */
.chat-msg.is-me.has-transfer .puff-transfer::after {
  content: "";
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  right: -6px;
  width: 8px;
  height: 16px;
  background-color: #FA9D3B;
  clip-path: polygon(100% 50%, 0 0, 0 100%);
  border-radius: 1px;
  z-index: 2;
}

/* 对方：左侧小三角 */
.chat-msg.is-them.has-transfer .puff-transfer::after {
  content: "";
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  left: -6px;
  width: 8px;
  height: 16px;
  background-color: #FA9D3B;
  clip-path: polygon(0 50%, 100% 0, 100% 100%);
  border-radius: 1px;
  z-index: 2;
}


/* ============================================================
   翻译：从气泡独立出来，落到气泡下方（白底长方形，有空隙）
   ============================================================ */

/* 1. 气泡成为定位容器，且不裁切 */
.chat-bubble,
.chat-bubble-primary {
  position: relative !important;
  overflow: visible !important;
}

/* 2. 翻译块：绝对定位到气泡下边缘之外 */
.chat-bubble-trans-inline,
.chat-bubble-trans-chip {
  display: block !important;
  position: absolute !important;

  /* 关键：top 100% = 贴气泡底边，再往下推一段 = 空隙 */
  top: calc(100% + 6px) !important;
  left: 0 !important;

  /* 白底长方形 */
  background: #ffffff !important;
  color: #000000 !important;
  border: none !important;
  border-radius: 6px !important;
  padding: 6px 10px !important;
  width: fit-content !important;
  max-width: 100% !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08) !important;

  font-size: 12px !important;
  line-height: 1.5 !important;
  white-space: normal !important;
  z-index: 5 !important;
}

/* 3. 我方翻译靠右、对方翻译靠左 */
.chat-msg.is-me .chat-bubble-trans-inline,
.chat-msg.is-me .chat-bubble-trans-chip {
  left: auto !important;
  right: 0 !important;
}
.chat-msg.is-them .chat-bubble-trans-inline,
.chat-msg.is-them .chat-bubble-trans-chip {
  left: 0 !important;
  right: auto !important;
}

/* 4. 去掉气泡内部原来的分割线/小条样式 */
.chat-bubble-trans-inline {
  border-top: none !important;
  margin-top: 0 !important;
}

/* 5. 给有翻译的消息行底部腾出空间，避免翻译压到下一条 */
.chat-msg.is-me,
.chat-msg.is-them {
  padding-bottom: 40px !important;   /* 按翻译实际高度调，矮就 32px，高就 48px */
}

/* ============================================================
   清掉原文气泡里所有残留的线 / 空隙（保住左右三角）
   ============================================================ */

/* 1. 气泡本体：彻底不画线、不留底部空 */
.chat-bubble,
.chat-bubble-primary {
  border: none !important;
  border-top: none !important;
  border-bottom: none !important;
  outline: none !important;
  box-shadow: none !important;
  padding-bottom: 8.5px !important;
}

/* 2. 气泡内所有子元素：不许画横线 */
.chat-bubble *,
.chat-bubble-primary * {
  border-top: none !important;
  border-bottom: none !important;
}

/* 3. 气泡内所有伪元素：不画线（但排除掉你的三角）
      ⚠️ 这里用 :not 排除带 is-me/is-them 的三角层 */
.chat-bubble > *::before,
.chat-bubble > *::after {
  border-top: none !important;
  border-bottom: none !important;
}

/* 4. 翻译块自身也不带线 */
.chat-bubble-trans-inline,
.chat-bubble-trans-chip {
  border-top: none !important;
  border-bottom: none !important;
  margin-top: 0 !important;
}

/* 5. 关键：你的左右三角是挂在 .chat-bubble::before/::after 上的，
      上面没动它们，所以三角安全。这里再确认三角还在 */
.chat-msg.is-them .chat-bubble::before {
  /* 三角保留，不动 */
}
.chat-msg.is-me .chat-bubble::after {
  /* 三角保留，不动 */
}

/* ============================================================
   翻译独立后的收尾：只影响有翻译的气泡，普通气泡恢复原样
   ============================================================ */

/* 1. 先撤销全量 padding —— 所有消息行恢复原本间距 */
.chat-msg,
.chat-msg.is-me,
.chat-msg.is-them {
  padding-bottom: 0 !important;      /* 关键：把之前 40px 撤掉 */
}

/* 2. 气泡本体恢复原本内边距，文字到下边框回到正常 */
.chat-bubble,
.chat-bubble-primary {
  padding-bottom: 8.5px !important;  /* 你文字气泡的原值 */
  border: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
}

/* 3. 只有「有翻译」的消息行，才给它底部腾出空间 */
.chat-msg:has(.chat-bubble-trans-inline),
.chat-msg:has(.chat-bubble-trans-chip) {
  padding-bottom: 40px !important;   /* 按翻译高度调，矮就 32px */
}

/* 4. 气泡里残余的线和空，继续清掉 */
.chat-bubble *,
.chat-bubble-primary * {
  border-top: none !important;
  border-bottom: none !important;
}

/* ========== 气泡下边框空隙收小，和上边框一致 ========== */
.chat-bubble,
.chat-bubble-primary {
  padding-bottom: 8.5px !important;
  margin-bottom: 0 !important;
}
.chat-bubble > *,
.chat-bubble-primary > * {
  margin-bottom: 0 !important;
  padding-bottom: 0 !important;
}

