/* 我方翻译：底色跟随我方气泡，字体黑色 */
.chat-msg.is-me .chat-bubble-trans-inline,
.chat-msg.is-me .chat-bubble-trans-chip {
  left: auto !important;
  right: 0 !important;
  background: var(--dress-bubble-me-bg) !important;
  color: #000000 !important;
}

/* 对方翻译：底色跟随对方气泡，字体白色 */
.chat-msg.is-them .chat-bubble-trans-inline,
.chat-msg.is-them .chat-bubble-trans-chip {
  left: 0 !important;
  right: auto !important;
  background: var(--dress-bubble-them-bg) !important;
  color: #ffffff !important;
}

.chat-bubble-trans-inline {
  border-top: none !important;
  margin-top: 0 !important;
}


/* ============================================================
   清掉原文气泡里所有残留的线 / 空隙（保住左右三角）
   ============================================================ */

.chat-bubble,
.chat-bubble-primary {
  border: none !important;
  border-top: none !important;
  border-bottom: none !important;
  outline: none !important;
  box-shadow: none !important;
  padding-bottom: 8.5px !important;
}

.chat-bubble *,
.chat-bubble-primary * {
  border-top: none !important;
  border-bottom: none !important;
}

.chat-bubble > *::before,
.chat-bubble > *::after {
  border-top: none !important;
  border-bottom: none !important;
}

.chat-bubble-trans-inline,
.chat-bubble-trans-chip {
  border-top: none !important;
  border-bottom: none !important;
  margin-top: 0 !important;
}


/* ============================================================
   翻译独立后的收尾
   ============================================================ */

.chat-msg,
.chat-msg.is-me,
.chat-msg.is-them {
  padding-bottom: 0 !important;
}

.chat-bubble,
.chat-bubble-primary {
  padding-bottom: 8.5px !important;
  border: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
}

.chat-msg:has(.chat-bubble-trans-inline),
.chat-msg:has(.chat-bubble-trans-chip) {
  padding-bottom: 40px !important;
}

.chat-bubble *,
.chat-bubble-primary * {
  border-top: none !important;
  border-bottom: none !important;
}

/* ========== 气泡下边框空隙收小，和上边框一致 ========== */
.chat-bubble,
.chat-bubble-primary {
  padding-bottom: 8.5px !important;
  margin-bottom: 0 !important;
}
.chat-bubble > *,
.chat-bubble-primary > * {
  margin-bottom: 0 !important;
  padding-bottom: 0 !important;
}

/* ========== 翻译块下方：图标 + 「由微信提供翻译支持」 ========== */
.chat-bubble-trans-inline::after,
.chat-bubble-trans-chip::after {
  content: "由微信提供翻译支持";
  display: block;
  margin-top: 4px;

  font-size: 10px;
  color: #999999;
  line-height: 1.4;
  padding-left: 16px;

  background-image: url("https://imgbed.heliar.top/i/hFHULwUa87qUKidF_IMG_20260911_211843.webp");
  background-repeat: no-repeat;
  background-position: left center;
  background-size: 12px 12px;
}

/* ========== 翻译块：下方留白 ========== */
.chat-bubble-trans-inline,
.chat-bubble-trans-chip {
  padding: 6px 10px 8px !important;
}

/* ========== 有翻译的消息行：给翻译预留足够空间 ========== */
.chat-msg:has(.chat-bubble-trans-inline),
.chat-msg:has(.chat-bubble-trans-chip) {
  padding-bottom: 64px !important;
  margin-bottom: 8px !important;
}

/* ========== 滚动区底部留白加大，长消息不被底栏挡住 ========== */
.chat-thread-scroll {
  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 140px) !important;
}


/* ============================================================
   引用：强制左右留出空隙
   ============================================================ */

/* 1. 引用长条：外壳样式 */
.chat-qq-quote {
  position: absolute !important;
  top: calc(100% + 6px) !important;
  left: 0 !important;

  /* 浅黑灰底 + 白字 */
  background: #3a3a3a !important;
  border: 1px solid #4a4a4a !important;
  border-radius: 4px !important;

  padding: 0px 2px !important;
  box-sizing: border-box !important;

  display: block !important;
  width: fit-content !important;
  max-width: 100% !important;
  white-space: normal !important;
  word-break: break-word !important;
  overflow-wrap: anywhere !important;
  overflow: hidden !important;

  font-size: 11px !important;
  line-height: 1.6 !important;
  z-index: 5 !important;

  color: #ffffff !important;
}

/* 2. 强制内容层不贴边 */
.chat-qq-quote > *,
.chat-qq-quote-name,
.chat-qq-quote-text {
  padding-left: 0 !important;
  padding-right: 0 !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
}

.chat-qq-quote > * {
  max-width: 100% !important;
}

/* 3. 我方靠右、对方靠左 */
.chat-msg.is-me .chat-qq-quote {
  left: auto !important;
  right: 0 !important;
}
.chat-msg.is-them .chat-qq-quote {
  left: 0 !important;
  right: auto !important;
}

/* 4. 打通所有层，名字和内容同行 */
.chat-qq-quote * {
  display: inline !important;
  vertical-align: baseline !important;
  white-space: normal !important;
  word-break: break-word !important;
  overflow-wrap: anywhere !important;
  margin: 0 !important;
  padding: 0 !important;
  float: none !important;
}

/* 5. 名字 + 冒号：白色 */
.chat-qq-quote-name {
  font-size: 11px !important;
  color: #ffffff !important;
}
.chat-qq-quote-name::after {
  content: "：" !important;
  color: #ffffff !important;
}

/* 6. 内容：白色 */
.chat-qq-quote-text {
  font-size: 11px !important;
  color: #ffffff !important;
}

/* 7. 消息行留空间 */
.chat-msg:has(.chat-qq-quote) {
  padding-bottom: 60px !important;
}


/* ========== 时间戳：白色 ========== */
.chat-msg-time,
.chat-time,
.chat-msg-time *,
.chat-time * {
  color: #ffffff !important;
}

/* ========== 夜间模式：发送键强制显示同一张图 ========== */
html[data-theme="dark"] .chat-compose-icon.is-send.ready {
  display: block !important;
  width: 28px !important;
  height: 28px !important;
  background-color: transparent !important;
  background-image: url("https://imgbed.heliar.top/i/170fcf_sDxkiwaIr_6e4b1e02f1b8cf37097430b82c5f4dc8.webp") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  opacity: 1 !important;
  visibility: visible !important;
  transform: translateY(-5px) !important;
  color: transparent !important;
  font-size: 0 !important;
}

/* 暗色下也把里面的原生图标藏掉 */
html[data-theme="dark"] .chat-compose-icon.is-send.ready svg,
html[data-theme="dark"] .chat-compose-icon.is-send.ready i,
html[data-theme="dark"] .chat-compose-icon.is-send.ready img {
  opacity: 0 !important;
}

/* 暗色下别让伪元素盖住 */
html[data-theme="dark"] .chat-compose-icon.is-send.ready::before,
html[data-theme="dark"] .chat-compose-icon.is-send.ready::after {
  display: none !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* ========== 底栏上边框：去掉明显直线 ========== */
.chat-compose-bar {
  border: none !important;
  border-top: none !important;
  box-shadow: none !important;
}
